{"id":"ex-65-2","title":"الحفلات - Los Conciertos","description":"حضور حفلة","content":"الحفلات: el concierto، la entrada (تذكرة الحفل)، el escenario (المسرح): Compramos las entradas por internet.","vocabulary":[{"es":"el concierto","ar":"الحفلة الموسيقية"},{"es":"la entrada","ar":"تذكرة الدخول"},{"es":"el escenario","ar":"المسرح"},{"es":"el público","ar":"الجمهور"}],"examples":[{"es":"El público cantó todas las canciones.","ar":"غنى الجمهور كل الأغاني."}],"quizzes":[{"question":"«المسرح» (المنصة):","options":["el escenario","el público","la entrada","la sala"],"correct_answer":"el escenario","explanation":"el escenario يقدم عليه الفنانون."}]},
{"id":"ex-65-3","title":"الآلات الموسيقية - Los Instrumentos","description":"آلات شائعة","content":"الآلات: el piano، la batería (الطبول)، el violín، la flauta: Mi hermano toca la batería.","vocabulary":[{"es":"el piano","ar":"البيانو"},{"es":"la batería","ar":"الطبول"},{"es":"el violín","ar":"الكمان"},{"es":"la flauta","ar":"الناي"}],"examples":[{"es":"Aprendo a tocar el piano desde hace un año.","ar":"أتعلم العزف على البيانو منذ سنة."}],"quizzes":[{"question":"فعل العزف على آلة:","options":["tocar","cantar","sonar","escuchar"],"correct_answer":"tocar","explanation":"tocar + آلة = يعزف عليها."}]}
