{"id":"ex-69-1","title":"اختيار التخصص - Elegir Carrera","description":"التسجيل الجامعي","content":"الجامعة: la carrera (التخصص)، matricularse (يُسجّل)، la facultad (الكلية): Me matriculé en la facultad de ciencias.","vocabulary":[{"es":"la carrera","ar":"التخصص الجامعي"},{"es":"matricularse","ar":"يتسجل رسمياً"},{"es":"la facultad","ar":"الكلية"},{"es":"el grado","ar":"درجة البكالوريوس"}],"examples":[{"es":"Estudio la carrera de medicina.","ar":"أدرس تخصص الطب."}],"quizzes":[{"question":"«التخصص الجامعي» بالإسبانية:","options":["la carrera","la asignatura","el curso","la clase"],"correct_answer":"la carrera","explanation":"la carrera الدراسة الجامعية الكاملة."}]},
{"id":"ex-69-2","title":"الحياة الجامعية - Vida Universitaria","description":"المحاضرات والزملاء","content":"الحياة الجامعية: la asignatura، el semestre، los apuntes (الملاحظات): Tomo apuntes en cada clase.","vocabulary":[{"es":"el semestre","ar":"الفصل الدراسي"},{"es":"los apuntes","ar":"الملاحظات"},{"es":"la beca","ar":"المنحة"},{"es":"el compañero","ar":"الزميل"}],"examples":[{"es":"Conseguí una beca para estudiar.","ar":"حصلت على منحة للدراسة."}],"quizzes":[{"question":"«الملاحظات» (كلاس):","options":["los apuntes","los libros","los exámenes","los profesores"],"correct_answer":"los apuntes","explanation":"apuntes ما يدونه الطالب في الحصة."}]},
{"id":"ex-69-3","title":"الامتحانات - Los Exámenes","description":"التحضير والنتائج","content":"الامتحانات: estudiar para el examen، aprobar (ينجح)، suspender (يرسب): Aprobé todas las asignaturas.","vocabulary":[{"es":"aprobar","ar":"ينجح"},{"es":"suspender","ar":"يرسب"},{"es":"la nota","ar":"الدرجة"},{"es":"repasar","ar":"يراجع"}],"examples":[{"es":"Saqué buena nota en el examen final.","ar":"حصلت على درجة جيدة في الامتحان النهائي."}],"quizzes":[{"question":"«ينجح» في الامتحان:","options":["aprobar","suspender","repasar","estudiar"],"correct_answer":"aprobar","explanation":"aprobar اجتياز الامتحان."}]}
