{"id":"ex-78-2","title":"الادخار - Ahorrar Dinero","description":"بناء عادة الادخار","content":"الادخار: guardar dinero cada mes، el colchón (الاحتياطي): Es recomendable ahorrar el diez por ciento del sueldo.","vocabulary":[{"es":"ahorrar","ar":"يدّخر"},{"es":"el colchón financiero","ar":"الاحتياطي المالي"},{"es":"la hucha","ar":"حصالة النقود"},{"es":"el interés","ar":"الفائدة"}],"examples":[{"es":"Meto cincuenta euros en la hucha cada mes.","ar":"أضع خمسين يورو في الحصالة شهرياً."}],"quizzes":[{"question":"«يدّخر» مالاً:","options":["ahorrar","gastar","deber","cobrar"],"correct_answer":"ahorrar","explanation":"ahorrar حفظ جزء من الدخل."}]},
{"id":"ex-78-3","title":"الديون - Las Deudas","description":"القرض وسداده","content":"الديون: pedir un préstamo (يطلب قرضاً)، devolver las cuotas (يسدد الأقساط): Pedí un préstamo para el coche.","vocabulary":[{"es":"el préstamo","ar":"القرض"},{"es":"la cuota","ar":"القسط"},{"es":"la deuda","ar":"الدَّين"},{"es":"el banco","ar":"البنك"}],"examples":[{"es":"Pago la cuota del préstamo el día cinco.","ar":"أدفع قسط القرض في الخامس."}],"quizzes":[{"question":"«القسط» الشهري:","options":["la cuota","la deuda","el préstamo","la comisión"],"correct_answer":"la cuota","explanation":"la cuota جزء من الدين يدفع دورياً."}]}
