(function () {
  'use strict';
  // العربية: الاسم العدلي الترتيبي من 1 إلى 120 (صيغة المذكر لتناسب كلمة «الفصل»)
  function arOrdinal(n) {
    var u = ['', 'الأول', 'الثاني', 'الثالث', 'الرابع', 'الخامس', 'السادس', 'السابع', 'الثامن', 'التاسع'];
    var t = { 20: 'العشرون', 30: 'الثلاثون', 40: 'الأربعون', 50: 'الخمسون', 60: 'الستون', 70: 'السبعون', 80: 'الثمانون', 90: 'التسعون', 100: 'المئة' };
    function tens(x) { return t[Math.floor(x / 10) * 10]; }
    function part(x) {
      if (x < 10) return u[x];
      if (x === 10) return 'العاشر';
      if (x === 11) return 'الحادي عشر';
      if (x === 12) return 'الثاني عشر';
      if (x < 20) return u[x - 10] + ' عشر';
      if (x % 10 === 0) return t[x];
      var one = x % 10;
      return (one === 1 ? 'الحادي' : u[one]) + ' و' + tens(x);
    }
    if (n <= 100) return part(n);
    var r = n - 100;
    return 'المئة و' + part(r);
  }
  var RAW = window.LOCAL_CHAPTERS_RAW || [];
  var START_NUM = 25; // يكمل ترقيم الفصول 17-24 المعرّفة في index.html
  window.LOCAL_CHAPTERS_ALL = RAW.map(function (c, i) {
    var lessons = c.lessons.map(function (ls) {
      return Object.assign({ duration: 15, xp_reward: c.xp || 30 }, ls);
    });
    return Object.assign({}, c, { title: 'الفصل ' + arOrdinal(START_NUM + i) + ': ' + c.title, lessons: lessons });
  });
})();
